-- Thin Mt. Batulao seed for issue #4. PLACEHOLDER DATA: real Batulao content arrives in #5.
--
-- Applied to the hosted project by supabase/seed/seed-batulao.sh. Safe to run again: it
-- replaces every Batulao row.
--
-- Coordinates come from OpenStreetMap (© OpenStreetMap contributors, ODbL 1.0), fetched with
-- the Overpass API on 2026-10-10:
--   * Trail: ways 188934002, 51822692 (reversed), 188933995 and 188933999, joined end to end
--     from the jump-off by the road to the summit ("Batulao" + "Old Trail" + "Summit Trail").
--   * Summit: node 332020556 (Mount Batulao, ele 811). Camp 1: node 662722021.
--     Camp 5: node 662722016. Spring: node 3042655992.
-- Waypoint distance_m is the distance along the Trail to its nearest Trail vertex.

begin;

insert into public.destinations
  (id, name, region, summary_en, summary_fil, latitude, longitude, elevation_m,
   pack_version, map_path, map_bytes, is_placeholder, updated_at)
values
  ('batulao', 'Mt. Batulao', 'Nasugbu, Batangas',
   'Sample data for testing Destination Pack downloads. Real Batulao content is coming.',
   'Sample na data para subukan ang pag-download ng Destination Pack. Parating pa ang totoong nilalaman tungkol sa Batulao.',
   14.0399434, 120.8023782, 811,
   1, 'batulao.pmtiles', 4207071, true, now())
on conflict (id) do update set
  name = excluded.name, region = excluded.region,
  summary_en = excluded.summary_en, summary_fil = excluded.summary_fil,
  latitude = excluded.latitude, longitude = excluded.longitude, elevation_m = excluded.elevation_m,
  map_path = excluded.map_path, is_placeholder = excluded.is_placeholder, updated_at = now();

-- Trails cascade to their Waypoints.
delete from public.trails where destination_id = 'batulao';
delete from public.reference_passages where destination_id = 'batulao';

