insert into public.reference_passages (id, destination_id, topic, language, text, source) values
  ('batulao-overview-en', 'batulao', 'overview', 'en', 'PLACEHOLDER, not verified for hiking. Mt. Batulao is an 811 m peak on the Nasugbu, Batangas side of the Batangas–Cavite border. This sample Old Trail runs about 3.2 km from the jump-off to the summit, past numbered campsites.', 'Placeholder for issue #4, from OpenStreetMap data (ODbL)'),
  ('batulao-overview-fil', 'batulao', 'overview', 'fil', 'PLACEHOLDER, hindi pa beripikado para sa pag-akyat. Ang Mt. Batulao ay bundok na 811 m ang taas sa panig ng Nasugbu, Batangas, malapit sa hangganan ng Batangas at Cavite. Mga 3.2 km ang sample na Old Trail mula jump-off hanggang summit, at dumadaan ito sa mga may-numerong campsite.', 'Placeholder for issue #4, from OpenStreetMap data (ODbL)'),
  ('batulao-water-en', 'batulao', 'water', 'en', 'PLACEHOLDER, not verified for hiking. OpenStreetMap shows a spring near Camp 1, about 2.2 km from the jump-off. Carry enough water for the whole hike, and boil or filter any water you collect.', 'Placeholder for issue #4, from OpenStreetMap data (ODbL)'),
  ('batulao-water-fil', 'batulao', 'water', 'fil', 'PLACEHOLDER, hindi pa beripikado para sa pag-akyat. May bukal malapit sa Camp 1 sa OpenStreetMap, mga 2.2 km mula sa jump-off. Magdala ng sapat na tubig para sa buong akyat, at pakuluan o i-filter ang anumang tubig na kukunin.', 'Placeholder for issue #4, from OpenStreetMap data (ODbL)'),
  ('batulao-campsites-en', 'batulao', 'campsites', 'en', 'PLACEHOLDER, not verified for hiking. Campsites along the Old Trail are numbered Camp 1 to Camp 9 in OpenStreetMap. Camp 1 is at about 576 m and Camp 5 at about 635 m.', 'Placeholder for issue #4, from OpenStreetMap data (ODbL)'),
  ('batulao-campsites-fil', 'batulao', 'campsites', 'fil', 'PLACEHOLDER, hindi pa beripikado para sa pag-akyat. May numero ang mga campsite sa Old Trail sa OpenStreetMap, mula Camp 1 hanggang Camp 9. Nasa mga 576 m ang Camp 1 at nasa mga 635 m ang Camp 5.', 'Placeholder for issue #4, from OpenStreetMap data (ODbL)');

commit;
